head.script:
scwin.screenId = "jldods26000";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// [A] 초기 목록 미해결 — jldods26000: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldods26000.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.grd_relatedLawList_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_relatedLawList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_relatedLawList');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_relatedLawList'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (typeof scwin.link === 'function') { scwin.link(r["chrgInstId"], r["sprtRoomNo"], r["attachSeq"], r["attachFileNm"], r["sprtRoomContn"]); } else { console.error('[sdd] 행 동작 미정의: scwin.link (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.link'); } return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_relatedLawList.oncellclick' });
    }
};


///////// 4. 서브미션 콜백 영역 /////////



///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.link
 * @author Inswave
 * @date 2026. 09. 29
 * @param chrg_inst_id sprt_room_no attach_seq attach_file_nm sprt_room_contn
 * @returns
 * @hidden N
*/
scwin.link = function (chrg_inst_id, sprt_room_no, attach_seq, attach_file_nm, sprt_room_contn) {
    /* sdd-asis-lifecycle:begin fn_link — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (chrg_inst_id === "KRX") {
        scwin.fileDownload(sprt_room_no, attach_seq, attach_file_nm);
    } else {
        $c.win.openPopup((function (__u) { var __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(sprt_room_contn), { id: 'popup' }, {});
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fileDownload
 * @author Inswave
 * @date 2026. 09. 29
 * @param sprt_room_no attach_seq attach_file_nm
 * @returns
 * @hidden N
*/
scwin.fileDownload = function (sprt_room_no, attach_seq, attach_file_nm) {
    /* sdd-asis-lifecycle:begin fn_fileDownload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (attach_seq === "") {
        return;
    }
    $('#ipt_sprtRoomNo', $('#attachForm')).val(sprt_room_no);
    $('#ipt_attachSeq', $('#attachForm')).val(attach_seq);
    $('#ipt_attachFileNm', $('#attachForm')).val(attach_file_nm);
    $('#ipt_SCREN_ID', $('#attachForm')).val("/jldods26000/jldods26000.xml");
    $('#ipt_method', $('#attachForm')).val("searchBbsAttachFile2");
    $('#attachForm').submit();
    /* sdd-asis-lifecycle:end */
};
